const $=s=>document.querySelector(s);let data,tab='today',usedCommons=new Set();const LS='indiaV6State';const saved=JSON.parse(localStorage.getItem(LS)||'{}');const esc=s=>String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));const D=s=>new Date(s+'T12:00:00');const fmt=s=>new Intl.DateTimeFormat('it-IT',{weekday:'short',day:'numeric',month:'short'}).format(D(s));function persist(){localStorage.setItem(LS,JSON.stringify(Object.fromEntries(data.items.map(x=>[x.id,{favorite:x.favorite,visited:x.visited}]))))}function restore(){data.items.forEach(x=>Object.assign(x,saved[x.id]||{}))}
async function load(){data=await fetch('/data.json?v=6').then(r=>r.json());restore();let cs=[...new Set(data.items.map(x=>x.city).filter(Boolean))].sort();$('#city').innerHTML='<option value="">Tutte le città</option>'+cs.map(c=>`<option>${esc(c)}</option>`).join('');bind();hero();render();hydrateRealPhotos()}
function bind(){document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x===b));$('#filters').classList.toggle('hidden',tab!=='explore');render();hydrateRealPhotos()});$('#search').oninput=render;$('#city').onchange=render}
function current(){let n=new Date();return data.itinerary.find(x=>D(x.date)>=new Date(n.getFullYear(),n.getMonth(),n.getDate()))||data.itinerary.at(-1)}function cityOf(d){return ['Delhi','Varanasi','Khajuraho','Orchha','Gwalior','Agra','Jaipur','Jodhpur','Jaisalmer'].find(c=>d.base.includes(c)||d.title.includes(c))||''}function hero(){let d=current();$('#heroTitle').textContent=d.title;$('#heroSub').textContent=fmt(d.date)+' · '+d.base}
function controls(x,label){return `<div class="actions">${x.maps?`<a href="${esc(x.maps)}" target="_blank">Maps ↗</a>`:''}<button onclick="fav('${x.id}')">${x.favorite?'♥ Salvato':'♡ Salva'}</button><button class="${x.visited?'on':''}" onclick="done('${x.id}')">${x.visited?'✓ '+label:'○ '+label}</button></div>`}window.fav=id=>{let x=data.items.find(i=>i.id===id);x.favorite=!x.favorite;persist();render();hydrateRealPhotos()};window.done=id=>{let x=data.items.find(i=>i.id===id);x.visited=!x.visited;persist();render();hydrateRealPhotos()}
function card(x){if(x.type==='food')return food(x);if(x.type==='hotel')return stay(x);if(x.type==='transport')return transport(x);return `<article class="card"><div class="photo commons-photo" data-id="${x.id}" data-q="${esc(x.name+' '+x.city+' India')}"></div><div class="body"><div class="meta"><span class="badge">📍 ${esc(x.city)}</span></div><h3>${esc(x.name)}</h3><p>${esc(x.subtitle)}</p><p class="source commons-source" data-source="${x.id}">Foto reale: caricamento da Wikimedia Commons…</p>${controls(x,'Visitato')}</div></article>`}
function food(x){return `<article class="card">${x.photo?`<div class="photo" style="background-image:url('${x.photo}')"></div>`:''}<div class="body"><span class="badge">🍛 ${esc(x.city)}</span><h3>${esc(x.name)}</h3>${x.venue||x.area?`<div class="where"><b>📍 Dove provarlo</b><br>${esc(x.venue||x.area)}${x.area&&x.venue?` · ${esc(x.area)}`:''}</div>`:''}<div class="facts">${x.price?`<span>💰 ${esc(x.price)}</span>`:''}${x.when?`<span>🕐 ${esc(x.when)}</span>`:''}</div>${controls(x,'Provato')}</div></article>`}
function stay(x){return `<article class="card"><div class="body"><span class="badge">🏨 ${esc(x.city)}</span><h3>${esc(x.name)}</h3><p>${esc(x.notes)}</p>${controls(x,'Scelto')}</div></article>`}function transport(x){return `<article class="card"><div class="body"><span class="badge">🚆 ${esc(x.bookingStatus)}</span><h3>${esc(x.name)}</h3><p>${esc(x.subtitle)}${x.date?' · '+fmt(x.date):''}${x.departure?' · '+esc(x.departure)+(x.arrival?' → '+esc(x.arrival):''):''}</p>${controls(x,'Fatto')}</div></article>`}
function render(){let xs=data.items;if(tab==='itinerary')return $('#content').innerHTML='<div class="section-title"><h2>Itinerario</h2></div><div class="timeline">'+data.itinerary.map(x=>`<div class="day"><h3>${fmt(x.date)} · ${esc(x.title)}</h3><p>${esc(x.base)}</p></div>`).join('')+'</div>';if(tab==='today'){let d=current(),c=cityOf(d);xs=xs.filter(x=>x.date===d.date||x.city===c)}else if(tab==='food')xs=xs.filter(x=>x.type==='food');else if(tab==='stay')xs=xs.filter(x=>x.type==='hotel');else if(tab==='transport')xs=xs.filter(x=>x.type==='transport');else if(tab==='saved')xs=xs.filter(x=>x.favorite);else if(tab==='explore'){let q=$('#search').value.toLowerCase(),c=$('#city').value;xs=xs.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!c||x.city===c))}let grouped={};xs.forEach(x=>(grouped[x.city||'Viaggio']??=[]).push(x));$('#content').innerHTML=Object.entries(grouped).map(([c,a])=>`<section class="city-section"><div class="section-title"><h2>${esc(c)}</h2><span>${a.length}</span></div><div class="cards">${a.map(card).join('')}</div></section>`).join('')||'<p>Nessun elemento.</p>'}
async function commons(q){let u='https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrnamespace=6&gsrlimit=8&gsrsearch='+encodeURIComponent(q)+'&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=1000&format=json&origin=*';let j=await fetch(u).then(r=>r.json());let ps=Object.values(j.query?.pages||{});for(let p of ps){let ii=p.imageinfo?.[0],url=ii?.thumburl||ii?.url;if(url&&!usedCommons.has(url)&&/\.(jpe?g|png|webp)(\?|$)/i.test(url)){usedCommons.add(url);return {url,page:ii.descriptionurl||'',license:ii.extmetadata?.LicenseShortName?.value||'Wikimedia Commons',artist:(ii.extmetadata?.Artist?.value||'').replace(/<[^>]*>/g,'')}}}return null}
async function hydrateRealPhotos(){for(const el of document.querySelectorAll('.commons-photo')){if(el.dataset.done)return;el.dataset.done='1';try{let r=await commons(el.dataset.q);if(r){el.style.backgroundImage=`url("${r.url}")`;let s=document.querySelector(`[data-source="${el.dataset.id}"]`);if(s)s.innerHTML=`Foto reale · ${esc(r.license)}${r.artist?' · '+esc(r.artist):''}${r.page?` · <a href="${r.page}" target="_blank">fonte</a>`:''}`}}catch(e){let s=document.querySelector(`[data-source="${el.dataset.id}"]`);if(s)s.textContent='Foto reale non disponibile offline.'}}}
load();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');